export default function main({body}) {
  const email = body?.email;
  if (typeof email !== 'string' || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim())) throw Error('Provide a valid email address');
  return {email:email.trim()};
}

