export default function main({response,email}) {
  const data=response?.data;
  if (!data || typeof data.status !== 'string' || typeof data.email !== 'string' || data.email.toLowerCase() !== email.toLowerCase()) throw Error('Hunter returned an incomplete or mismatched assessment');
  if (!['valid','invalid','accept_all','webmail','disposable','unknown'].includes(data.status)) throw Error('Hunter returned an unexpected status');
  return {valid:data.status === 'valid'};
}

