export default function main({body,email}) {
  const fit=body?.properties?.customer_fit;
  const signals=fit?.top_signals_formated ?? fit?.top_signals_formatted;
  if (!fit || typeof fit.score !== 'number' || !Number.isFinite(fit.score) || typeof signals !== 'string') throw Error('MadKudu returned an incomplete customer fit');
  if (typeof body.email !== 'string' || body.email.toLowerCase() !== email.toLowerCase()) throw Error('MadKudu returned a different email');
  const text=`⭐ New hot lead: ${email}...\n\n${signals}`;
  if(text.length>4096) throw Error('Telegram message exceeds the size limit');
  return {qualified:fit.score>60,text};
}
